package identity

// Authentication and quota counting share validity checks: revoked external
// identities must not occupy browser-session slots.
const validAuthSessionSQL = `a.revoked_at IS NULL AND a.absolute_expires_at>now() AND a.auth_epoch=i.auth_epoch AND u.status='enabled' AND u.deleted_at IS NULL AND (a.external_identity_id IS NULL OR EXISTS(SELECT 1 FROM external_identities e JOIN oidc_identity_providers p ON p.id=e.provider_id WHERE e.id=a.external_identity_id AND e.user_id=u.id AND p.enabled AND p.version=a.oidc_provider_version)) AND (a.ldap_identity_id IS NULL OR EXISTS(SELECT 1 FROM ldap_identities e JOIN ldap_identity_providers p ON p.id=e.provider_id WHERE e.id=a.ldap_identity_id AND e.user_id=u.id AND p.enabled AND p.version=a.ldap_provider_version)) AND (a.passkey_id IS NULL OR EXISTS(SELECT 1 FROM passkey_credentials p WHERE p.id=a.passkey_id AND p.user_id=u.id AND p.revoked_at IS NULL)) AND (a.contact_id IS NULL OR EXISTS(SELECT 1 FROM verified_contacts v CROSS JOIN identity_contact_settings s WHERE v.id=a.contact_id AND v.user_id=u.id AND v.version=a.contact_version AND s.version=a.contact_settings_version AND s.sms_login_enabled AND EXISTS(SELECT 1 FROM notification_channels n WHERE n.id=s.sms_channel AND n.enabled AND n.version=a.contact_channel_version)))`
